import * as C from './core.mjs';
import {TrailGPS} from './gps.mjs';
import {Vault,importBackup} from './storage.mjs';
import {portrait,battlefield,pickupIcon} from './art.mjs';
import {EncounterRadar} from './radar.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const STARTERS=['capuchin','macaque','langur','mandrill','spider','howler'];
let state=null,vault=null,selected='capuchin',tab='walk',selectedId=null,busy=false,combatBusy=false,lastCheckpoint=0,toastTimer,scores=null,collectionPage=0,collectionFilter='owned',animation='idle',pendingMove=null,lastDiscovery=0,ultraConfirm=false,practiceExpanded=false;
let gpsInfo={reason:'Paused · choose Start walking when ready.',mph:null,accuracy:null};
const preferenceKey='monkey-trails-display-v2';
let prefs={reducedMotion:false,battery:false,sound:false,vibration:false,keepAwake:true};
try{prefs={...prefs,...JSON.parse(localStorage.getItem(preferenceKey)||'{}')};}catch{}
const radar=new EncounterRadar(),team=()=>C.team(state),collection=()=>C.sanctuary(state),active=()=>state.run.monkey;
const species=p=>C.SPECIES[p.species]||{},name=p=>p.nickname||species(p).name||'Companion',pstats=p=>C.stats(p,C.equipped(state,p));
const feet=n=>Math.max(0,Math.ceil((Number(n)||0)/C.FEET-1e-6)).toLocaleString(),canPrepare=()=>['trail','camp'].includes(state.run.phase),canSwap=()=>state.run.phase==='camp'||(state.run.phase==='trail'&&state.run.distance===0);
function applyPreferences(){document.body.classList.toggle('reduce-motion',prefs.reducedMotion);document.body.classList.toggle('battery-saver',prefs.battery);}
applyPreferences();
const gps=new TrailGPS(fix=>{
  if(!state||state.run.phase!=='trail'||tab!=='walk')return pause();
  if(ultraConfirm){radar.observe(fix,state);renderGPS();return;}
  const oldCache=state.run.discoveries??state.run.nextCache,oldPhase=state.run.phase;
  C.advance(state,fix.meters,fix.east,fix.north);radar.observe(fix,state);animation='walk';
  const discovered=(state.run.discoveries??state.run.nextCache)!==oldCache;
  if(discovered){lastDiscovery=Date.now();feedback();}
  if(state.run.phase!=='trail')pause('Encounter ready · tracking paused. Stop somewhere safe.');
  if(discovered||oldPhase!==state.run.phase||Date.now()-lastCheckpoint>=5000)void checkpoint(discovered);render();
},info=>{gpsInfo=info;renderGPS();},fix=>{
  if(!state||state.run.phase!=='trail'||tab!=='walk')return;
  const before=radar.view(state).withinRadius;radar.observe(fix,state);
  if(before!==radar.view(state).withinRadius)render();
});
function toast(message){clearTimeout(toastTimer);$('toast').textContent=message;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,4800);}
function feedback(){if(prefs.vibration&&navigator.vibrate)navigator.vibrate(25);if(prefs.sound)try{const a=new (window.AudioContext||window.webkitAudioContext)(),o=a.createOscillator(),g=a.createGain();o.connect(g);g.connect(a.destination);o.frequency.value=660;g.gain.setValueAtTime(.035,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+.12);o.start();o.stop(a.currentTime+.13);o.onended=()=>a.close();}catch{}}
function saveStatus({text,kind}){$('save-status').textContent=text;$('save-dot').className=`save-dot ${kind}`;$('cloud-restore').hidden=kind!=='conflict';}
function starters(){$('starters').innerHTML=STARTERS.map(id=>{const p=C.SPECIES[id];return `<button type="button" class="starter ${selected===id?'selected':''}" data-starter="${id}" aria-pressed="${selected===id}">${portrait({species:id,types:[],stage:0})}<span>${esc(p.name)}</span></button>`;}).join('');$('starter-trait').textContent=`${C.SPECIES[selected].role||C.SPECIES[selected].title} · ${C.SPECIES[selected].trait}`;}
starters();$('starters').addEventListener('click',e=>{const b=e.target.closest('[data-starter]');if(b){selected=b.dataset.starter;starters();}});
function loginBusy(value){busy=value;document.querySelectorAll('#save-form button,#practice-button,#import-button').forEach(b=>b.disabled=value);}
async function showGame(next,nextVault){vault=nextVault;state=next;tab='walk';selectedId=active().id;await radar.bind(vault);$('creature-password').value='';$('welcome').hidden=true;$('game').hidden=false;$('login-message').textContent='';$('mode-label').textContent=state.mode==='practice'?'PRACTICE · UNRANKED':'GPS · FOREGROUND ONLY';if(state.run.battle)state.run.battle.ready=false;render();window.scrollTo(0,0);}
async function enter(name,password,options){loginBusy(true);$('login-message').textContent='Opening your encrypted sanctuary…';const nextVault=new Vault(saveStatus);try{await showGame(await nextVault.open(name,password,options),nextVault);}catch(error){$('login-message').textContent=error.message;}finally{loginBusy(false);}}
$('save-form').addEventListener('submit',e=>{e.preventDefault();if(!busy)void enter($('creature-name').value,$('creature-password').value,{create:e.submitter?.value!=='open',species:selected,mode:'gps'});});
$('practice-button').addEventListener('click',async()=>{if(busy)return;loginBusy(true);$('login-message').textContent='Opening the separate practice sanctuary…';const v=new Vault(saveStatus),name='Trail Practice',password='practice-only-not-ranked';try{let s;try{s=await v.open(name,password,{mode:'practice'});}catch(e){if(!e.message.startsWith('No save found'))throw e;s=await v.open(name,password,{create:true,species:selected,mode:'practice'});}await showGame(s,v);}catch(e){$('login-message').textContent=e.message;}finally{loginBusy(false);}});
$('import-button').addEventListener('click',()=>{if(!busy)$('backup-file').click();});
$('backup-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file||busy)return;const name=$('creature-name').value,password=$('creature-password').value;if(!name.trim()||!password){$('login-message').textContent='Enter the backup creature name and password first.';e.target.value='';return;}if(file.size>1100000){$('login-message').textContent='Backup file is too large.';e.target.value='';return;}if(!confirm('Restore this encrypted backup on this device? Existing device progress will be kept as a recovery copy.')){e.target.value='';return;}loginBusy(true);try{const mode=await importBackup(name,password,await file.text());await enter(name,password,{mode});}catch(error){$('login-message').textContent=error.message;}finally{e.target.value='';loginBusy(false);}});
function pause(message='Paused · choose Start walking to resume.'){gps.stop();animation='idle';gpsInfo={reason:message,mph:null,accuracy:null};renderGPS();if(state&&vault)void checkpoint(true);}
async function checkpoint(urgent=false){if(!state||!vault)return;lastCheckpoint=Date.now();try{await vault.checkpoint(state,urgent);}catch(e){saveStatus({text:e.message,kind:'error'});}}
function chip(type){const e=C.ELEMENTS[type];return e?`<span class="type-chip" style="--element:${e.color}">${e.icon} ${esc(e.name)}</span>`:'';}
function chips(p){return p.types?.length?p.types.map(chip).join(''):'<span class="type-chip adaptable">◇ Adaptable</span>';}
function bar(value,max,label,kind=''){const n=Math.max(0,Number(value)||0),m=Math.max(1,Number(max)||1);return `<div class="meter-label"><span>${esc(label)}</span><span>${Math.round(n)} / ${Math.round(m)}</span></div><div class="meter ${kind}" role="progressbar" aria-label="${esc(label)}" aria-valuenow="${Math.round(n)}" aria-valuemin="0" aria-valuemax="${Math.round(m)}"><i style="width:${C.clamp(n/m*100,0,100)}%"></i></div>`;}
function miniHealth(p){return `<div class="mini-health"><i style="width:${C.clamp(p.hp/pstats(p).hp*100,0,100)}%"></i></div>`;}
function resources(){const r=state.run;return `<div class="fruit-row"><span>${pickupIcon('fruit')} ${r.fruit} fruit</span><span>${r.items.bondCharm??0} Bond Charms</span></div><div class="resources">${Object.entries(C.ELEMENTS).map(([id,e])=>`<div class="resource" style="--element:${e.color}"><span>${e.icon} ${esc(e.name)}</span><b>${r.essence[id]??0}</b></div>`).join('')}</div>`;}
function journal(){return `<details class="panel journal"><summary>Trail journal <span>${state.log.length} recent moments</span></summary><ol class="log">${[...state.log].reverse().map(t=>`<li>${esc(t)}</li>`).join('')}</ol></details>`;}
function uiIcon(id){const paths={leaf:'<path d="M4 20Q1 4 21 3Q22 20 4 20ZM4 20 16 8M10 14V9m0 5h5"/>',rival:'<path d="m5 3 16 18M19 3 3 19M3 15l6 6m6-18 6 6M3 3l5 1-4 4-1-5Zm18 18-5-1 4-4 1 5Z"/>',camp:'<path d="m3 18 9-15 9 15H3ZM12 3v15m-4 3 8-3m-8 0 8 3"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',play:'<path d="m9 5 10 7-10 7V5Z"/>',pack:'<path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M5 7h14l1 14H4L5 7ZM5 8v4l7 3 7-3V8"/>'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[id]||paths.leaf}</svg>`;}
function practiceControls(){return `<details class="practice-tools" ${practiceExpanded?'open':''}><summary>${uiIcon('play')}<strong>Take a practice walk</strong><span>＋</span></summary><div class="direction-buttons">${Object.entries(C.DIRECTIONS).map(([d,t])=>`<button data-action="practice-step" data-id="${d}"><b>${d}</b><span>${C.ELEMENTS[t].name}</span><small>+250 ft</small></button>`).join('')}</div><p>Separate practice save · no GPS or ranked progress</p></details>`;}
function walkingBonuses(){const b=state.run.bonuses;return `<div class="active-bonuses">${[b.ribbon>0?`Trail Ribbon · ${feet(b.ribbon)} ft left`:'',b.scent>0?`Treasure Scent · ${b.scent} discoveries`:'',b.feather?'Scout Feather · next sighting':'',b.campSeed?'Campfire Seed · next camp':''].filter(Boolean).map(t=>`<span>${esc(t)}</span>`).join('')}</div>`;}
function teamStrip(action='inspect'){const members=team();return `<div class="team-strip">${Array.from({length:3},(_,i)=>{const p=members[i];return p?`<button class="team-slot ${p.id===state.run.activeId?'active':''} ${p.hp<=0?'knocked-out':''}" data-action="${action}" data-id="${esc(p.id)}">${portrait(p,{state:p.hp<=0?'knockout':'idle'})}<strong>${esc(name(p))}</strong>${miniHealth(p)}<small>${p.hp<=0?'Knocked out':`Lv ${p.level} · ${Math.round(p.hp)} HP`}</small><span class="slot-elements">${(p.types||[]).map(t=>`<span style="color:${C.ELEMENTS[t].color}">${C.ELEMENTS[t].icon}</span>`).join('')||'◇'}</span></button>`:`<button class="team-slot empty" data-action="team" aria-label="Team slot ${i+1} empty"><span>＋</span><strong>Slot ${i+1}</strong><small>Recruit a companion</small></button>`;}).join('')}</div>`;}
function radarView(){
  const u=state.run.ultra,rv=radar.view(state)||{},bearing=Number(rv.bearing??u?.bearing??0),dist=Number(rv.distance??u?.challengeRemaining??0),ring=Math.min(92,Math.max(29,dist/(600*C.FEET)*92)),x=140+Math.sin(bearing*Math.PI/180)*ring,y=140-Math.cos(bearing*Math.PI/180)*ring,showing=u&&!['claimed','battle'].includes(u.status);
  const ticks=Array.from({length:32},(_,i)=>`<path d="M140 31v${i%4===0?6:3}" transform="rotate(${i*11.25} 140 140)"/>`).join('');
  return `<div class="radar-wrap"><div class="radar" role="img" aria-label="Encounter radar. North Leaf, east Storm, south Fire, west Water. Rings are not roads."><svg class="radar-grid" viewBox="0 0 280 280" aria-hidden="true"><defs><radialGradient id="radar-paper"><stop stop-color="#f9f6e9"/><stop offset="1" stop-color="#e7ead5"/></radialGradient><pattern id="radar-dots" width="10" height="10" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".55" fill="#668277" opacity=".22"/></pattern></defs><circle cx="140" cy="140" r="109" fill="url(#radar-paper)" stroke="#9cad92" stroke-width=".7"/><circle cx="140" cy="140" r="105" fill="url(#radar-dots)"/><g fill="none" stroke="#a9b89b" stroke-width=".7"><circle cx="140" cy="140" r="35"/><circle cx="140" cy="140" r="69"/><circle cx="140" cy="140" r="101"/><path d="M140 39v202M39 140h202" stroke-dasharray="2 6"/></g><g stroke="#6f8b76" stroke-width="1">${ticks}</g><g fill="#6d8677" font-size="8" font-family="Arial,sans-serif"><text x="169" y="127">200 ft</text><text x="193" y="101">400 ft</text><text x="213" y="77">600 ft</text></g><path d="m140 43-3 8h6Z" fill="#c28a35"/>${showing?`<g transform="translate(${x},${y})"><circle r="15" fill="#edd28d" stroke="#a87629"/><path d="M0-8 2-2 8 0 2 2 0 8-2 2-8 0-2-2Z" fill="#705225"/></g>`:''}</svg><span class="radar-bearing north"><b>N</b>Leaf</span><span class="radar-bearing east"><b>E</b>Storm</span><span class="radar-bearing south"><b>S</b>Fire</span><span class="radar-bearing west"><b>W</b>Water</span><div class="player-marker">${portrait(active(),{state:gps.active?animation:'idle'})}</div></div><span class="radar-caption">ENCOUNTER RADAR <i></i> YOUR ROUTE, YOUR CHOICE</span></div>`;
}
function ultraCard(){const u=state.run.ultra;if(!u||['claimed','battle'].includes(u.status))return '';const p={species:u.species,types:C.SPECIES[u.species].types,stage:0},owned=collection().some(x=>x.species===u.species)||u.revealed||state.run.bonuses.feather>0,rv=radar.view(state)||{},eligible=u.status==='ready'||rv.withinRadius||u.safeAlternative&&u.challengeRemaining<=0;return `<section class="ultra-card"><div class="ultra-head"><div class="ultra-portrait ${owned?'':'silhouette'}">${portrait(p,{state:'arrival'})}</div><div><span class="eyebrow">ULTRA SIGHTING · ${esc(u.difficulty||'Challenging')}</span><h2>${owned?esc(C.SPECIES[u.species].name):'An extraordinary presence'}</h2><p>${u.safeAlternative?`${feet(u.challengeRemaining)} ft on any safe route`:rv.calibrating?'Calibrating position':`${feet(rv.distance)} ft · approx. ${Math.round(rv.bearing??u.bearing??0)}°`}</p></div></div><p class="fine">${u.safeAlternative?'Same Ultra, same rewards. Only accepted walking advances this challenge.':u.tracked?'Your selected target stays anchored. Radar cannot tell whether land is safe or public.':'Optional hunt. You can always choose a safe route instead.'}</p><div class="button-row">${!u.tracked?'<button data-action="ultra-track" class="primary">Track sighting</button>':''}${eligible?'<button data-action="ultra-preview" class="primary">Battle available</button>':''}${!u.safeAlternative?'<button data-action="ultra-safe">Cannot safely reach this location</button>':''}</div>${eligible?'<p class="fine">Stop safely, then confirm Begin Battle.</p>':''}</section>`;}
function discoveryText(){const d=state.run.lastDiscovery;if(!d)return 'Your next discovery is waiting.';if(d.category==='essence')return `${d.amount||1} ${C.ELEMENTS[d.id]?.name||''} essence added to your pack`;if(d.category==='fruit')return `${d.amount||2} training fruit added to your pack`;if(d.category==='fragment')return `${C.GEAR[d.id]?.name||'Equipment'} fragment found`;return `${C.ITEMS[d.id]?.name||'Trail supply'} added to your pack`;}
function walk(){
  const r=state.run;if(r.phase==='dead')return death();if(['battle','replacement'].includes(r.phase))return battle();if(r.phase==='befriend')return capture();if(r.phase==='camp')return camp();
  const interval=C.discoveryInterval(state),cacheLeft=Math.max(0,r.nextCache-r.distance),encounterLeft=Math.max(0,r.nextEncounter-r.distance),progress=C.clamp((1-cacheLeft/interval)*100,0,100);
  return `<div class="walk-layout"><section class="walk-main" data-mode="${state.mode}"><div class="trail-strip"><div class="distance-block"><span>EXPEDITION ${String(state.meta.runs).padStart(2,'0')}</span><strong>${feet(r.distance)}<small> ft</small></strong></div><div class="tracking-state"><b id="walking-state">${gps.active?'Walking':'Paused'}</b><span id="gps-quality">GPS waiting</span></div><span class="speed-limit"><b>10</b><small>MPH LIMIT</small></span></div>${radarView()}<div class="team-heading"><span>ON YOUR TEAM</span><b>${team().length} / 3</b></div>${teamStrip()}<div class="tracking-controls"><button data-action="tracking" id="tracking-button" class="primary" ${state.mode==='practice'?'hidden':''}>Start walking</button>${state.mode==='practice'?practiceControls():''}<div class="gps-status-row"><p id="gps-status" class="gps-status"></p><p id="gps-meta" class="gps-meta"></p></div></div><div class="discovery ${Date.now()-lastDiscovery<1500?'discovered':''}"><div class="discovery-icon">${uiIcon('leaf')}</div><div class="discovery-copy"><span>NEXT DISCOVERY</span><strong>${feet(cacheLeft)}<small> ft away</small></strong></div><span class="discovery-spark">${uiIcon('pack')}</span><svg class="vine-meter" viewBox="0 0 320 25" preserveAspectRatio="none" aria-label="${Math.round(progress)} percent toward next discovery"><path class="vine-track" pathLength="100" d="M5 14C35 3 64 24 96 14S155 3 190 14 252 25 314 10"/><path class="vine-fill" pathLength="100" stroke-dasharray="${progress} 100" d="M5 14C35 3 64 24 96 14S155 3 190 14 252 25 314 10"/><path class="vine-leaves" d="M49 13q-9-12-15-5 2 8 15 5m74-5q5-11 13-6-1 8-13 6m107 9q8-12 17-7-3 9-17 7"/></svg></div>${walkingBonuses()}<div class="next-events"><span>${uiIcon('rival')}<i>Next rival<b>${feet(encounterLeft)} ft</b></i></span><span>${uiIcon('camp')}<i>Trail camp<b>${feet(r.nextCamp-r.distance)} ft</b></i></span></div><div class="recent-discovery">${uiIcon(r.lastDiscovery?'pack':'leaf')}<span>${esc(discoveryText())}</span></div></section><aside class="walk-aside">${ultraCard()}${journal()}</aside></div>`;
}
function statusList(p){return Object.entries(p.status||{}).map(([id,v])=>`<span class="status">${esc(id)} ${typeof v==='object'?v.turns??v.duration??'':v}r</span>`).join('');}
function fighter(p,isEnemy){const st=isEnemy?C.stats(p):pstats(p);return `<div class="fighter ${isEnemy?'enemy-fighter':''}">${portrait(p,{enemy:isEnemy,state:p.hp<=0?'knockout':isEnemy&&['attack','cast','signature'].includes(animation)?'hit':!isEnemy?animation:'idle'})}<h3>${esc(name(p))}</h3><div class="fighter-meta">Lv ${p.level} <span>${chips(p)}</span></div>${bar(p.hp,st.hp,'Health',isEnemy?'enemy':'')}${bar(p.energy,st.maxEnergy,'Energy','energy')}<div class="statuses">${statusList(p)}</div></div>`;}
function enemyStrip(enemies,current){return `<div class="enemy-strip" aria-label="Enemy team">${enemies.map(p=>`<div class="enemy-mini ${p===current?'active':''} ${p.hp<=0?'knocked-out':''}">${portrait(p,{enemy:true,state:p.hp<=0?'knockout':'idle'})}<span>${esc(species(p).name)}</span><i style="--hp:${Math.max(0,p.hp/C.stats(p).hp*100)}%"></i></div>`).join('')}</div>`;}
function moveTiming(p,id,b){const m=C.MOVES[id],cool=Math.max(0,(p.cooldowns?.[id]||0)-b.round),left=m.uses?Math.max(0,m.uses-(p.uses?.[id]||0)):null,relayBlock=m.switch&&(p.status.root||!team().some(x=>x.id!==p.id&&x.hp>0));return {blocked:cool>0||left===0||relayBlock,label:relayBlock?` · ${p.status.root?'Rooted':'Needs teammate'}`:cool?` · ${cool}r cooldown`:left!==null?` · ${left} uses left`:''};}
function battle(){
  const r=state.run,b=r.battle,p=active(),e=b.enemy,m=b.enemyAction?.type==='switch'?{name:'Switch teammate',cost:0,desc:'The rival spends its action bringing in a reserve.'}:C.MOVES[b.intent],replace=r.phase==='replacement';
  return `<section class="battle-panel"><div class="battle-title"><div><span class="eyebrow">${b.ultra?'ULTRA ENCOUNTER':esc(b.style||'WILD ENCOUNTER')}</span><h2>${b.ultra?esc(C.SPECIES[e.species].name):'A team on the trail'}</h2></div><span class="tag">ROUND ${b.round??b.turn??1}</span></div>${enemyStrip(b.enemies||[e],e)}<div class="battlefield">${battlefield(e.types)}${fighter(p,false)}<div class="versus">VS</div>${fighter(e,true)}</div><div class="player-bench">${teamStrip('inspect')}</div>${!b.ready&&!replace?'<div class="notice"><strong>Tracking is paused.</strong> Look up and stop in a safe place before playing.</div><button class="primary wide" data-action="ready">I have stopped safely · begin battle</button>':replace?`<div class="notice"><strong>${esc(name(p))} needs a rest.</strong> Choose a conscious teammate. This replacement gives the enemy no extra action.</div>${switchChoices(true)}`:`<div class="intent"><span>Enemy telegraph</span><strong>${esc(m?.name||b.intent||'Preparing an action')}</strong><small>${m?`${m.cost} energy · ${esc(m.desc)}`:''}</small></div><div class="moves">${Array.from({length:4},(_,i)=>{const id=p.loadout[i],move=C.MOVES[id];if(!move)return '<button disabled class="move">No ability equipped</button>';const timing=moveTiming(p,id,b);return `<button class="move" data-action="move" data-id="${id}" ${p.energy<move.cost||combatBusy||timing.blocked?'disabled':''} style="--move:${C.ELEMENTS[move.type]?.color||'#d8e6bc'}"><span class="move-meta">${move.cost} EN ${move.power?`×${C.moveEffect(move,e.types)}`:''}${timing.label}</span><strong>${esc(move.name)}</strong><small>${(move.types||[move.type]).map(t=>C.ELEMENTS[t]?.name||'Physical').join(' + ')}</small></button>`;}).join('')}</div><div class="battle-actions"><button data-action="switch-menu" ${p.status.root?'disabled':''}>⇄ ${p.status.root?'Rooted':'Switch'}</button><button data-action="battle-heal">＋ Supplies</button><button data-action="move-info">ⓘ Abilities</button></div><p class="fine battle-tip">Switching uses this turn. Effects stay with each monkey and tick once per round.</p>`}</section>${journal()}`;
}
function switchChoices(forced=false){const e=state.run.battle.enemy;return `<div class="switch-list">${team().filter(p=>p.id!==state.run.activeId).map(p=>`<button data-action="${forced?'replace':'switch-preview'}" data-id="${p.id}" ${p.hp<=0?'disabled':''}>${portrait(p,{state:p.hp<=0?'knockout':'idle'})}<span><strong>${esc(name(p))}</strong><small>${Math.round(p.hp)} / ${pstats(p).hp} HP · ${p.energy} EN</small><small>${e.types.map(t=>`${C.ELEMENTS[t].name} ×${C.effectiveness(t,p.types)}`).join(' · ')}</small><small>${statusList(p)||'No status effects'}${state.run.battle.hazard?` · Hazard: ${esc(state.run.battle.hazard.name||state.run.battle.hazard)}`:''}</small></span><b>${p.hp<=0?'KO':'→'}</b></button>`).join('')}</div>`;}
function profile(p){const st=pstats(p);return `<div class="profile-art">${portrait(p,{state:p.hp<=0?'knockout':'idle'})}<div><span class="eyebrow">${esc(species(p).role||species(p).rarity||'COMPANION')}</span><h2>${esc(name(p))}</h2><p>${esc(C.formName(p))}</p><div class="type-chips">${chips(p)}</div><span class="fine">Lv ${p.level} · Bond ${p.bond||0} · Stage ${p.stage}/3</span></div></div><p class="muted">${esc(species(p).trait)}</p>${bar(p.hp,st.hp,'Health')}${bar(p.energy,st.maxEnergy,'Energy','energy')}<div class="stat-grid">${[['atk','Attack'],['def','Defense'],['speed','Speed'],['hp','Max HP']].map(([k,l])=>`<span><b>${st[k]}</b>${l}</span>`).join('')}</div>`;}
function evolutionOffers(p){return `<div class="evolution-grid">${Object.keys(C.ELEMENTS).map(t=>{let o;try{o=C.evolutionPreview(state,t,p.id);}catch{return '';}if(!o)return '';return `<button class="evolution" data-action="evolution-preview" data-id="${t}" data-monkey="${p.id}"><span style="color:${C.ELEMENTS[t].color}">${C.ELEMENTS[t].icon}</span><strong>${esc(o.name||o.formName||C.ELEMENTS[t].name)}</strong><small>Lv ${o.level??o.requiredLevel??3} · ${Object.entries(o.cost||{}).map(([x,n])=>`${n} ${C.ELEMENTS[x]?.name||x}`).join(' + ')}</small><b>Preview →</b></button>`;}).join('')}</div>`;}
function loadout(p){return `<div class="loadout">${Array.from({length:4},(_,i)=>`<label>Ability ${i+1}<select data-slot="${i}" data-monkey="${p.id}" ${!canPrepare()||i===0?'disabled':''}>${!p.loadout[i]?'<option value="">Choose ability</option>':''}${C.unlocked(p).map(id=>`<option value="${id}" ${p.loadout[i]===id?'selected':''}>${esc(C.MOVES[id].name)} · ${C.MOVES[id].cost} EN</option>`).join('')}</select></label>`).join('')}</div><p class="fine">A reliable zero-energy action stays equipped. Changes are available between encounters.</p>`;}
function teamView(){const p=state.collection[selectedId]||active();selectedId=p.id;return `<div class="section-title"><div><span class="eyebrow">EXPEDITION TEAM</span><h2>Three companions. One adventure.</h2></div><span class="tag">${team().length} / 3</span></div>${teamStrip('select-monkey')}<p class="fine">${canSwap()?'Manage the three slots before heading out. Used companions keep their expedition injuries.':'Team changes are available before walking and at earned trail camps.'}</p>${canSwap()?`<div class="button-row">${[0,1,2].map(i=>`<button data-action="party-menu" data-id="${i}">Manage slot ${i+1}</button>`).join('')}</div>`:''}<div class="two-col section-gap"><section class="panel">${profile(p)}<div class="training-row"><div><strong>Train to level ${p.level+1}</strong><small>${C.trainingCost(p).fruit} fruit + ${C.trainingCost(p).xp} battle XP · ${p.training??0} XP available</small></div><button data-action="train" data-id="${p.id}" ${!canPrepare()||!state.run.party.includes(p.id)||p.hp<=0||p.level>=60||state.run.fruit<C.trainingCost(p).fruit||p.training<C.trainingCost(p).xp?'disabled':''}>Train</button></div><label for="monkey-nickname">Nickname</label><div class="input-row"><input id="monkey-nickname" maxlength="24" value="${esc(name(p))}"><button data-action="rename" data-id="${p.id}">Save</button></div><p class="fine">Highest discovered form: ${p.highestForm?esc(C.formName({...p,...p.highestForm})):esc(C.formName(p))}. Discovered paths remain after defeat.</p></section><div class="stack"><section class="panel"><h2>Evolution paths</h2><p class="muted">Preview the appearance, strengths, weaknesses, abilities and resource requirements before choosing.</p>${evolutionOffers(p)}</section><section class="panel"><h2>Four equipped abilities</h2>${loadout(p)}</section></div></div>`;}
function sanctuaryView(){const roster=Object.entries(C.SPECIES),owned=new Set(collection().map(p=>p.species)),filtered=collectionFilter==='owned'?roster.filter(([id])=>owned.has(id)):roster,perPage=12,pages=Math.max(1,Math.ceil(filtered.length/perPage));collectionPage=Math.min(collectionPage,pages-1);return `<div class="section-title"><div><span class="eyebrow">PERMANENT SANCTUARY</span><h2>Your wild companions</h2><p>${owned.size} / ${roster.length} species · ${collection().length} individuals</p></div><span class="collection-badge">${owned.size}<small>discovered</small></span></div><div class="segmented"><button data-action="collection-filter" data-id="owned" aria-pressed="${collectionFilter==='owned'}">Collected</button><button data-action="collection-filter" data-id="all" aria-pressed="${collectionFilter==='all'}">Field guide · ${roster.length}</button></div><p class="fine">New companions are always kept safely. A full expedition team sends new captures to the sanctuary.</p><div class="collection-grid">${filtered.slice(collectionPage*perPage,(collectionPage+1)*perPage).map(([id,s])=>{const individuals=collection().filter(p=>p.species===id),p=individuals[0]||{species:id,types:s.types||[],stage:0};return `<button class="collection-card ${s.rarity==='ultra'?'ultra':''} ${individuals.length?'':'uncollected'}" data-action="species" data-id="${id}"><span class="collection-number">${String(s.number||roster.findIndex(([x])=>x===id)+1).padStart(2,'0')}</span>${portrait(p)}<strong>${esc(s.name)}</strong><small>${individuals.length?`${individuals.length} collected`:`${esc(s.rarity||'Wild')} · discover`}</small><span class="slot-elements">${(s.types||[]).map(t=>`<span style="color:${C.ELEMENTS[t].color}">${C.ELEMENTS[t].icon}</span>`).join('')||'◇'}</span></button>`;}).join('')}</div><div class="pagination"><button data-action="collection-page" data-id="-1" ${collectionPage===0?'disabled':''}>← Previous</button><span>${collectionPage+1} / ${pages}</span><button data-action="collection-page" data-id="1" ${collectionPage===pages-1?'disabled':''}>Next →</button></div>`;}
function captureDisabled(c){return c.claimed||c.attempts>=c.maxAttempts||(!(c.ultra&&c.guaranteed)&&state.run.items.bondCharm<1);}
function capture(){const c=state.run.capture;if(!c)return '';return `<section class="panel capture-panel"><span class="eyebrow">A NEW FRIENDSHIP?</span><h1>Befriend a wild companion.</h1><p>Recruit one opponent per encounter. Choose who to invite.</p><div class="capture-candidates">${c.candidates.map(p=>{const chance=C.captureChance(state,p.id),duplicates=collection().filter(x=>x.species===p.species).length;return `<article class="capture-card">${portrait(p,{state:'victory'})}<h2>${esc(species(p).name)}</h2><div class="type-chips">${chips(p)}</div><p>${esc(species(p).trait)}</p><div class="capture-odds"><strong>${Math.round(chance>1?chance:chance*100)}%</strong><span>${c.guaranteed?'Guaranteed invitation':`${Math.max(0,c.maxAttempts-c.attempts)} attempts left`}</span></div><label for="capture-name-${esc(p.id)}">Nickname <small>Optional · up to 24 characters</small></label><input id="capture-name-${esc(p.id)}" maxlength="24" placeholder="${esc(species(p).name)}">${duplicates?'<p class="fine">Duplicate species: keep the individual or choose species bond materials after recruitment.</p>':''}<button class="primary wide" data-action="befriend" data-id="${p.id}" ${captureDisabled(c)?'disabled':''}>${c.ultra&&c.guaranteed?'Invite Ultra · no charm needed':'Use 1 Bond Charm'}</button><p class="fine">${team().length<3?'An open team slot is available.':'Your team is full. New friends wait in your sanctuary until a camp or your next expedition.'}</p></article>`;}).join('')}</div><p class="fine">Failures build persistent bad-luck protection. Combat bond bonuses improve the displayed chance.</p><button class="text-button" data-action="capture-skip">Continue without recruiting</button></section>`;}
function camp(){const r=state.run;return `<section class="panel camp-panel"><span class="eyebrow">A SAFE PLACE TO PREPARE</span><h1>Canopy camp</h1><p>${r.camp?.heals??0} camp recovery uses remain.</p>${teamStrip('select-monkey')}${team().map(p=>`<div class="item-card"><div><h3>${esc(name(p))}</h3><p>${Math.round(p.hp)} / ${pstats(p).hp} HP${p.hp<=0?' · Revive before replacing.':''}</p></div><button data-action="${p.hp<=0?'revive':'camp-heal'}" data-id="${p.id}" ${(p.hp<=0?!(r.items.revive>0):!(r.camp?.heals>0))?'disabled':''}>${p.hp<=0?`Revive (${r.items.revive||0})`:'Camp recovery'}</button></div>`).join('')}<div class="button-row section-gap"><button data-action="team">Manage team</button><button data-action="pack">Craft & prepare</button><button data-action="camp-leave" class="primary">Continue expedition</button></div><p class="fine">Conscious companions can be replaced here. A knocked-out teammate needs a revival supply first. Returning companions retain injuries.</p></section>${journal()}`;}
function pack(){const r=state.run,p=state.collection[selectedId]||active();return `<div class="two-col"><section class="panel"><span class="eyebrow">EXPEDITION PACK</span><h2>Supplies & discoveries</h2><label for="supply-target">Use supplies on</label><select id="supply-target">${team().map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(name(x))} · ${Math.round(x.hp)} HP</option>`).join('')}</select>${Object.entries(C.ITEMS).map(([id,item])=>`<div class="item-card"><span class="item-art">${pickupIcon(id)}</span><div><h3>${esc(item.name)} <b>×${r.items[id]??0}</b></h3><p>${esc(item.desc)}</p></div><button data-action="item" data-id="${id}" ${!(r.items[id]>0)||r.phase==='dead'||['befriend','replacement'].includes(r.phase)?'disabled':''}>${['trailRibbon','treasureScent','scoutFeather','campfireSeed'].includes(id)?'Activate':'Use'}</button></div>`).join('')}<div class="section-gap">${resources()}</div><p class="fine">Temporary supplies reset after full-team defeat. Collection, bonds, equipment and discovered paths persist.</p></section><div class="stack"><section class="panel"><h2>Permanent equipment</h2><label for="gear-target">Equip this individual</label><select id="gear-target">${collection().map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(name(x))}</option>`).join('')}</select>${Object.entries(C.GEAR).map(([id,g])=>{const tier=state.meta.gear[id]||0,on=p.equipment?.[g.slot]===id;return `<div class="gear-card"><span class="item-art">${pickupIcon(id)}</span><div><h3>${esc(g.name)} ${tier?`+${tier}`:''}</h3><p>${tier?`${g.amount?`+${g.amount*tier} ${g.stat?.toUpperCase()||''} · `:''}${esc(g.desc||g.slot)}`:`${state.meta.fragments?.[id]??0} fragments · craft to unlock`}</p></div><button data-action="equip" data-id="${id}" ${!tier||on||!canPrepare()?'disabled':''}>${on?'Equipped':'Equip'}</button></div>`;}).join('')}</section><section class="panel"><h2>Campcraft & exchange</h2><p class="muted">Craft at an earned trail camp. Bond Charm: 2 fruit + 1 charm material. Revival Seed: 8 fruit + 4 materials. Materials in pack: ${r.items.charmMaterial??0}.</p><div class="button-row"><button data-action="craft" data-id="charm">Craft Bond Charm</button><button data-action="craft" data-id="revive">Craft revival supply</button></div><div class="exchange-grid"><label>Give essence<select id="exchange-from">${Object.entries(C.ELEMENTS).map(([id,e])=>`<option value="${id}">${e.name} (${r.essence[id]??0})</option>`).join('')}</select></label><span>→</span><label>Receive essence<select id="exchange-to">${Object.entries(C.ELEMENTS).map(([id,e])=>`<option value="${id}" ${id==='earth'?'selected':''}>${e.name}</option>`).join('')}</select></label></div><button data-action="exchange" class="wide">Exchange spare essence · 4 → 1</button><p class="fine">Fragments are permanent. Ordinary discoveries do not routinely drop complete high-tier equipment.</p>${Object.entries(C.GEAR).map(([id,g])=>`<button class="craft-gear" data-action="craft" data-id="${id}">Craft ${esc(g.name)} <span>${state.meta.fragments?.[id]??0} fragments</span></button>`).join('')}</section></div></div>`;}
function recordRows(records){return records?.length?records.map((h,i)=>`<div class="record"><span class="tag">${i+1}</span><div><strong>${esc(h.name)}</strong><small>${esc(h.form)} · ${Number(h.feet).toLocaleString()} ft · ${Number(h.wins)} wins${h.mode==='practice'?' · PRACTICE':''}</small></div><b>${Number(h.score).toLocaleString()}</b></div>`).join(''):'<p class="muted">Finish an expedition to record its story here.</p>';}
function records(){return `<h2>Your trail stories</h2><div class="stat-grid"><span><b>${state.meta.best.toLocaleString()}</b>Best score</span><span><b>${state.meta.runs}</b>Expeditions</span><span><b>${state.meta.legacy}</b>Legacy</span><span><b>${collection().length}</b>Companions</span></div>${recordRows(state.meta.history)}<h3 class="section-gap">Wild Companions leaderboard</h3><p class="fine">GPS expeditions only. Casual client-reported scores; no coordinates are published.</p><button class="wide" data-action="scores" ${state.mode==='practice'?'disabled':''}>Refresh leaderboard</button>${scores?recordRows(scores):''}`;}
function settings(){return `<h2>Make the trail yours</h2><p class="muted">Effects are optional. Tracking runs only in the foreground.</p><label for="difficulty-setting">Expedition difficulty<select id="difficulty-setting" ${state.run.distance>0&&state.run.phase!=='dead'?'disabled':''}>${[['relaxed','Relaxed'],['standard','Standard'],['challenging','Challenging']].map(([id,label])=>`<option value="${id}" ${state.difficulty===id?'selected':''}>${label}</option>`).join('')}</select><small>Choose before walking or after an expedition ends. Enemy depth stays tied to distance.</small></label>${[['reducedMotion','Reduced motion','Still portraits and simpler transitions.'],['battery','Battery saving','Limit ambient animations and effects.'],['sound','Sound effects','Quiet discovery and battle notes.'],['vibration','Vibration','A short tap when supplies arrive.'],['keepAwake','Keep screen awake','Optional while tracking; your browser may release it.']].map(([id,label,desc])=>`<label class="setting-row"><span><strong>${label}</strong><small>${desc}</small></span><input type="checkbox" data-pref="${id}" ${prefs[id]?'checked':''}></label>`).join('')}<div class="button-row section-gap"><button data-action="export">Export encrypted backup</button><button data-action="sync">Sync now</button></div><button class="text-button wide" data-action="records">Trail stories & leaderboard</button>`;}
function death(){const h=state.meta.history[0];return `<section class="panel run-end"><span class="eyebrow">EVERY COMPANION COMES HOME</span><div class="end-art">${team().map(p=>portrait(p,{state:'knockout'})).join('')}</div><h1>A brave expedition.</h1><p>${feet(state.run.distance)} feet · ${state.run.wins} victories · ${h?.score?.toLocaleString()||0} points</p><div class="notice">Your ${collection().length} companions, equipment, bonds and evolution discoveries remain safe. The next expedition earns levels and active forms anew.</div><h3>Choose up to three for your next trail</h3><div class="restart-party">${collection().map((p,i)=>`<label><input type="checkbox" name="restart-member" value="${p.id}" ${i<3?'checked':''}>${portrait(p)}<span>${esc(name(p))}</span></label>`).join('')}</div><button class="primary wide" data-action="restart">Begin the next expedition</button><p class="fine">Temporary supplies and expedition injuries reset on a new expedition.</p></section>${journal()}`;}
function renderGPS(){if($('gps-status'))$('gps-status').textContent=state?.mode==='practice'?'':gpsInfo.reason;if($('gps-meta'))$('gps-meta').textContent=gpsInfo.mph==null?'':`${gpsInfo.mph.toFixed(1)} mph`;if($('tracking-button'))$('tracking-button').textContent=gps.active?'Pause walking':'Start walking';if($('walking-state'))$('walking-state').textContent=state?.mode==='practice'?'Practice':gps.active?'Walking':'Paused';if($('gps-quality'))$('gps-quality').textContent=state?.mode==='practice'?'Unranked trail':gpsInfo.accuracy==null?'GPS waiting':`GPS ±${Math.round(gpsInfo.accuracy)} m`;}
function render(){
  if(!state)return;document.body.classList.add('in-game');document.body.classList.toggle('is-walk',tab==='walk');$('creature-label').textContent=`${state.name} · ${state.mode==='practice'?'Practice sanctuary':'Expedition '+state.meta.runs}`;document.querySelectorAll('[data-action="tab"]').forEach(b=>b.setAttribute('aria-current',b.dataset.id===tab?'page':'false'));
  $('view').innerHTML=tab==='walk'?walk():tab==='team'?teamView():tab==='sanctuary'?sanctuaryView():pack();
  document.querySelectorAll('#view [data-action="craft"]').forEach(b=>{const recipe=b.dataset.id==='charm'?{fruit:2,material:1}:b.dataset.id==='revive'?{fruit:8,material:4}:null;b.disabled=state.run.phase!=='camp'||(recipe?state.run.fruit<recipe.fruit||(state.run.items.charmMaterial||0)<recipe.material:(state.meta.fragments[b.dataset.id]||0)<C.CONFIG.fragmentCost);});
  if(state.run.phase==='battle'&&!state.run.battle.ready)document.querySelectorAll('#view [data-action="item"]').forEach(b=>b.disabled=true);
  document.querySelectorAll('#view [data-action="item"][data-id="bondCharm"]').forEach(b=>{b.disabled=true;b.textContent='Befriend';});
  renderGPS();
}
function modal(content,label='Trail details'){$('dialog-content').innerHTML=content;$('inspect-dialog').setAttribute('aria-label',label);if(!$('inspect-dialog').open)$('inspect-dialog').showModal();}
function closeModal(){const stopped=ultraConfirm;ultraConfirm=false;$('inspect-dialog').close();pendingMove=null;if(stopped&&gps.active)pause('Ultra confirmation closed · Start walking to resume.');}
function switchPreview(id){const p=state.collection[id],e=state.run.battle.enemy;modal(`<span class="eyebrow">${pendingMove?'RELAY TARGET':'SWITCH PREVIEW'}</span>${profile(p)}<div class="notice">${pendingMove?`${esc(C.MOVES[pendingMove].name)} will bring this teammate in.`:'Switching spends this turn. The incoming teammate may receive the enemy attack.'} Status effects remain attached.</div><h3>Incoming matchup</h3><div class="matchups">${e.types.map(t=>`<span style="color:${C.ELEMENTS[t].color}">${C.ELEMENTS[t].name} ×${C.effectiveness(t,p.types)}</span>`).join('')}</div><p class="fine">${state.run.battle.hazard?`Entry hazard: ${esc(state.run.battle.hazard.name||state.run.battle.hazard)}`:'No entry hazard is visible.'}</p><button class="primary wide" data-action="switch-confirm" data-id="${id}">${pendingMove?'Use relay ability':'Confirm switch · uses turn'}</button>`,'Switch teammate');}
function openEvolution(type,id){const p=state.collection[id],o=C.evolutionPreview(state,type,id);if(!o)return;const preview=o.monkey||o.preview||{...p,types:o.types||[type],stage:p.stage+1};modal(`<span class="eyebrow">EVOLUTION PREVIEW</span>${profile(preview)}<h3>${esc(o.specialization||C.ELEMENTS[type].name+' path')}</h3><p>${esc(o.desc||o.passive||'A new combat specialization, silhouette and elemental techniques.')}</p><div class="matchups">${Object.keys(C.ELEMENTS).map(t=>`<span style="color:${C.ELEMENTS[t].color}">${C.ELEMENTS[t].name} ×${C.effectiveness(t,preview.types)}</span>`).join('')}</div><h3 class="section-gap">New ability decisions</h3><p>${(o.moves||o.abilities||C.unlocked(preview).filter(x=>!C.unlocked(p).includes(x))).map(x=>esc(C.MOVES[typeof x==='string'?x:x.id]?.name||x)).join(' · ')||'Deepen this role and review your loadout.'}</p><p>Requires level ${o.level??o.requiredLevel??3} · ${Object.entries(o.cost||{}).map(([x,n])=>`${n} ${C.ELEMENTS[x]?.name||x} essence`).join(' + ')}</p><button class="primary wide" data-action="evolve" data-id="${type}" data-monkey="${id}" ${!canPrepare()?'disabled':''}>Commit to this evolution</button>`,'Evolution preview');}
document.addEventListener('change',e=>{try{if(e.target.matches('[data-slot]')&&state){C.setMove(state,Number(e.target.dataset.slot),e.target.value,e.target.dataset.monkey);void checkpoint(true);render();}if(e.target.matches('[data-pref]')){prefs[e.target.dataset.pref]=e.target.checked;localStorage.setItem(preferenceKey,JSON.stringify(prefs));applyPreferences();if((prefs.battery||!prefs.keepAwake)&&gps.lock){gps.lock.release().catch(()=>{});gps.lock=null;}}if(e.target.id==='difficulty-setting'&&Object.keys(C.CONFIG.difficulty).includes(e.target.value)&&(state.run.distance===0||state.run.phase==='dead')){state.difficulty=e.target.value;void checkpoint(true);}if(e.target.id==='gear-target'){selectedId=e.target.value;render();}if(e.target.id==='supply-target')selectedId=e.target.value;if(e.target.name==='restart-member'&&document.querySelectorAll('[name="restart-member"]:checked').length>3){e.target.checked=false;toast('Choose at most three companions.');}}catch(error){toast(error.message);render();}});
document.addEventListener('click',async e=>{
  const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;if(a==='close-dialog'){closeModal();return;}if(!state)return;
  try{
    if(a==='tab'||['team','pack'].includes(a)){const next=a==='tab'?id:a;if(next!=='walk')pause('Paused while using menus. Return to Walk to resume.');tab=next;closeModal();render();window.scrollTo(0,0);return;}
    if(a==='tracking'){if(gps.active){pause();await checkpoint(true);}else if(state.mode==='gps'&&state.run.phase==='trail'&&tab==='walk')await gps.start({wakeLock:prefs.keepAwake&&!prefs.battery});renderGPS();return;}
    if(a==='sync'){await checkpoint(true);void vault.sync();toast('Encrypted checkpoint queued. See save status below.');return;}
    if(a==='export'){await checkpoint(false);const data=await vault.export(),url=URL.createObjectURL(new Blob([data],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=`monkey-trails-${state.name.replace(/[^A-Za-z0-9_-]/g,'-')}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
    if(a==='cloud'){pause();if(!confirm('Load the cloud checkpoint? An encrypted recovery copy of device progress will be kept.'))return;state=await vault.loadCloud();await radar.bind(vault);if(state.run.battle)state.run.battle.ready=false;render();return;}
    if(a==='settings'){pause('Paused while using settings.');modal(settings(),'Settings');return;}
    if(a==='records'){pause();modal(records(),'Trail stories');return;}
    if(a==='scores'){b.disabled=true;b.textContent='Reading scores…';scores=await vault.leaderboard();modal(records(),'Trail stories');return;}
    if(a==='select-monkey'){selectedId=id;render();return;}
    if(a==='inspect'){pause('Paused while inspecting a companion.');modal(`${profile(state.collection[id])}<button class="primary wide" data-action="inspect-team" data-id="${id}">Inspect abilities & evolution</button>`,'Companion');return;}
    if(a==='inspect-team'){selectedId=id;tab='team';pause();closeModal();render();window.scrollTo(0,0);return;}
    if(a==='collection-filter'){collectionFilter=id;collectionPage=0;render();return;}
    if(a==='collection-page'){collectionPage+=Number(id);render();return;}
    if(a==='species'){const s=C.SPECIES[id],individuals=collection().filter(p=>p.species===id),p=individuals[0]||{species:id,types:s.types||[],stage:0};modal(`<div class="species-hero">${portrait(p)}<span class="eyebrow">${esc(s.rarity)} · ${esc(s.role)}</span><h2>${esc(s.name)}</h2><div class="type-chips">${chips(p)}</div></div><p>${esc(s.trait)}</p>${individuals.length?`<h3>Your individuals</h3>${individuals.map(x=>`<button class="individual-row" data-action="inspect-team" data-id="${x.id}"><strong>${esc(name(x))}</strong><span>Bond ${x.bond||0} · ${team().some(y=>y.id===x.id)?'Team':'Sanctuary'} →</span></button>`).join('')}`:'<p class="notice">Keep exploring: this species belongs to the encounter roster. Ultras appear through optional hunts.</p>'}<p class="fine">Species bond materials: ${state.meta.bondMaterials[id]||0}</p><h3>Learnable techniques</h3><p class="fine">${(s.learnset||[]).map(x=>esc(C.MOVES[x]?.name||x)).join(' · ')}</p>`,'Species field guide');return;}
    if(a==='party-menu'){modal(`<h2>Choose team slot ${Number(id)+1}</h2><p class="fine">Injuries stay with individuals. Knocked-out teammates require revival before replacement.</p><div class="switch-list">${collection().map(p=>`<button data-action="party-set" data-id="${p.id}" data-slot-index="${id}">${portrait(p,{state:p.hp<=0?'knockout':'idle'})}<span><strong>${esc(name(p))}</strong><small>${Math.round(p.hp)} HP · Lv ${p.level}${team().some(x=>x.id===p.id)?' · In team':''}</small></span><b>→</b></button>`).join('')}</div>`,'Team selection');return;}
    if(a==='evolution-preview'){openEvolution(id,b.dataset.monkey);return;}
    if(a==='switch-menu'){pendingMove=null;modal(`<h2>Switch teammate</h2><p class="fine">Switching spends this turn. Preview health, matchup and hazards first.</p>${switchChoices()}`,'Switch teammate');return;}
    if(a==='switch-preview'){switchPreview(id);return;}
    if(a==='move-info'){modal(`<h2>Equipped techniques</h2>${active().loadout.map(x=>{const m=C.MOVES[x];return `<div class="item-card"><div><h3>${esc(m.name)} · ${m.cost} EN</h3><p>${esc(m.desc)}</p><small>${(m.types||[m.type]).map(t=>C.ELEMENTS[t]?.name||'Physical').join(' + ')}${m.types?.length?' · damage split across both elements':''}</small></div></div>`;}).join('')}`,'Abilities');return;}
    if(a==='battle-heal'){modal(`<h2>Battle supplies</h2><p class="fine">Supplies spend your action. Revival can target a fallen teammate from Pack.</p>${Object.entries(C.ITEMS).filter(([x])=>['berry','tonic','salve'].includes(x)).map(([x,item])=>`<div class="item-card"><div><h3>${esc(item.name)} ×${state.run.items[x]||0}</h3><p>${esc(item.desc)}</p></div><button data-action="battle-item" data-id="${x}" ${!state.run.items[x]?'disabled':''}>Use</button></div>`).join('')}`,'Battle supplies');return;}
    if(a==='ultra-preview'){ultraConfirm=true;const u=state.run.ultra;modal(`<span class="eyebrow">AN ULTRA AWAITS</span><div class="species-hero">${portrait({species:u.species,types:C.SPECIES[u.species].types,stage:0},{state:'arrival'})}<h2>${esc(C.SPECIES[u.species].name)}</h2></div><p>A new Ultra joins your sanctuary after victory, with no rare capture item required.</p><div class="notice">Look up. Stop in a safe, permitted place before beginning. Expedition distance is paused while this confirmation is open.</div><button class="primary wide" data-action="ultra-begin">I have stopped safely · Begin Battle</button>`,'Begin Ultra battle');return;}
    if(a==='practice-step'){if(state.mode!=='practice'||state.run.phase!=='trail')return;const v={N:[0,1],S:[0,-1],E:[1,0],W:[-1,0]}[id];if(!v)return;C.advance(state,C.RESOURCE_STEP,v[0]*C.RESOURCE_STEP,v[1]*C.RESOURCE_STEP);animation='walk';}
    else if(a==='ready')C.readyBattle(state);
    else if(a==='move'){if(combatBusy)return;const m=C.MOVES[id];if(m.switch&&team().filter(p=>p.hp>0).length>1){pendingMove=id;modal(`<h2>${esc(m.name)}</h2><p>${esc(m.desc)}</p>${switchChoices()}`,'Relay teammate');return;}C.turn(state,id);animation=m.signature?'signature':m.type!=='neutral'?'cast':m.power?'attack':'cast';combatBusy=true;feedback();setTimeout(()=>{combatBusy=false;animation='idle';render();},650);}
    else if(a==='switch-confirm'){if(pendingMove)C.turn(state,pendingMove,false,{targetId:id});else C.switchMonkey(state,id);closeModal();}
    else if(a==='replace')C.chooseReplacement(state,id);
    else if(a==='item'||a==='battle-item'){const target=a==='battle-item'?active().id:($('supply-target')?.value||selectedId||active().id);if(['ribbon','scent','feather','seed','trailRibbon','treasureScent','scoutFeather','campfireSeed'].includes(id))C.activateBonus(state,id);else C.useItem(state,id,target);closeModal();}
    else if(a==='train')C.train(state,id);
    else if(a==='rename'){C.renameMonkey(state,id,$('monkey-nickname').value.trim());toast('Nickname saved.');}
    else if(a==='evolve'){C.evolve(state,id,b.dataset.monkey);closeModal();toast('Evolution discovered. Review your four abilities.');}
    else if(a==='equip')C.equip(state,id,$('gear-target').value);
    else if(a==='party-set'){const ids=team().map(p=>p.id);ids[Number(b.dataset.slotIndex)]=id;C.setParty(state,ids.filter(Boolean));closeModal();}
    else if(a==='camp-heal')C.campHeal(state,id);
    else if(a==='revive')C.useItem(state,'revive',id);
    else if(a==='camp-leave'){C.leaveCamp(state);tab='walk';pause('Camp complete · Start walking to resume.');}
    else if(a==='befriend'){const candidate=state.run.capture.candidates.find(p=>p.id===id),wasDuplicate=collection().some(p=>p.species===candidate.species),nickname=$(`capture-name-${id}`).value.trim(),result=C.befriend(state,id,{duplicate:'keep',nickname});if(result.success){const p=result.monkey;modal(`<span class="eyebrow">WELCOME TO YOUR SANCTUARY</span>${profile(p)}<label for="monkey-nickname">Nickname your new companion</label><div class="input-row"><input id="monkey-nickname" maxlength="24" value="${esc(name(p))}"><button data-action="rename" data-id="${p.id}">Save</button></div><div class="notice">${team().some(x=>x.id===p.id)?'Your companion fills an open team slot.':'This individual is safely in your sanctuary. Bring them along at a camp or before your next expedition.'}</div><h3>Compare with your team</h3>${teamStrip('inspect')}<div class="button-row"><button class="primary" data-action="close-dialog">Keep ${esc(name(p))}</button>${wasDuplicate&&typeof C.convertDuplicate==='function'?`<button data-action="convert-duplicate" data-id="${p.id}">Convert duplicate to species bond</button>`:''}</div>`,'New companion');feedback();}else toast('They are still cautious. Bad-luck protection improves the next displayed chance.');}
    else if(a==='convert-duplicate'){C.convertDuplicate(state,id);closeModal();toast('Duplicate converted to species-specific bond materials.');}
    else if(a==='capture-skip')C.skipBefriend(state);
    else if(a==='ultra-track'){C.trackUltra(state);radar.view(state);toast('Ultra selected. Choose a safe route.');}
    else if(a==='ultra-safe'){C.safeUltraAlternative(state);toast('Same Ultra preserved. Walk the challenge on any safe route.');}
    else if(a==='ultra-begin'){C.beginUltra(state,radar.view(state)||{});pause('Ultra encounter · tracking paused.');C.readyBattle(state);closeModal();}
    else if(a==='craft'){C.craft(state,id);toast('Crafting complete.');}
    else if(a==='exchange'){C.exchangeEssence(state,$('exchange-from').value,$('exchange-to').value);toast('Essence exchanged.');}
    else if(a==='restart'){const ids=[...document.querySelectorAll('[name="restart-member"]:checked')].map(x=>x.value);if(!ids.length)throw Error('Choose at least one companion.');C.restart(state);C.setParty(state,ids);radar.clear();tab='walk';selectedId=active().id;pause();}
    else return;
    if(state.run.phase!=='trail'&&gps.active)pause('Tracking paused for the encounter.');render();if(a==='restart')window.scrollTo(0,0);await checkpoint(true);
  }catch(error){toast(error.message);}
});
$('inspect-dialog').addEventListener('click',e=>{if(e.target===$('inspect-dialog'))closeModal();});
document.addEventListener('toggle',e=>{if(e.target.matches('.practice-tools'))practiceExpanded=e.target.open;},true);
$('inspect-dialog').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
document.addEventListener('visibilitychange',()=>{document.body.classList.toggle('app-inactive',document.hidden);if(document.hidden){pause('Tracking paused while hidden. Resume manually; the gap earns no distance.');closeModal();void checkpoint(true);}else renderGPS();});
window.addEventListener('pagehide',()=>{gps.stop();void checkpoint(true);});
window.addEventListener('online',()=>{if(vault)void vault.sync();});
window.addEventListener('offline',()=>{if(state)saveStatus({text:'Offline · encrypted device saves continue; Firestore will retry.',kind:'offline'});});
setInterval(()=>{if(vault&&state?.mode==='gps'&&vault.dirty&&!document.hidden)void vault.sync();},20000);
